WITH deduped AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY city ORDER BY rating DESC, id) AS dedup_rank FROM suppliers QUALIFY dedup_rank = 1) SELECT CASE WHEN rating >= 3.8 THEN 'PREMIUM' ELSE 'STANDARD' END AS rating_tier, country, SUM(rating) AS total_rating, ROUND(SUM(rating) / NULLIF(COUNT(CASE WHEN city = 'Tokyo' THEN 1 END), 0), 2) AS rating_per_tokyo, COUNT(CASE WHEN country = 'DE' THEN 1 END) AS de_count, ROUND(AVG(rating), 2) AS avg_rating, SORT_ARRAY(COLLECT_SET(city)) AS city_list, COUNT(CASE WHEN city = 'New York' THEN 1 END) AS new_york_count FROM deduped GROUP BY GROUPING SETS ((CASE WHEN rating >= 3.8 THEN 'PREMIUM' ELSE 'STANDARD' END, country), (CASE WHEN rating >= 3.8 THEN 'PREMIUM' ELSE 'STANDARD' END), ()) HAVING rating_per_tokyo < 0 ORDER BY total_rating DESC NULLS LAST;
